"""Join data/orders.db with data/payments.csv and write data/discrepancies.csv.

Report columns: order_or_payment_id, category, order_amount, paid_amount
Categories: MISSING_PAYMENT, UNKNOWN_ORDER, AMOUNT_MISMATCH, DUPLICATE_OVERPAY.
Orders paid twice whose payments sum exactly to the order amount are counted as
RECONCILED_SPLIT and do NOT appear in the report. Prints a summary including
the matched-clean count.
"""
import csv
import os
import sqlite3
from collections import defaultdict

ROOT = os.path.dirname(os.path.abspath(__file__))
DATA_DIR = os.path.join(ROOT, "data")


def main() -> None:
    conn = sqlite3.connect(os.path.join(DATA_DIR, "orders.db"))
    try:
        orders = {
            oid: amt
            for oid, amt in conn.execute("SELECT order_id, amount_cents FROM orders")
        }
    finally:
        conn.close()

    by_order = defaultdict(list)  # order_id -> [(payment_id, amount_cents), ...]
    orphans = []
    with open(os.path.join(DATA_DIR, "payments.csv"), newline="") as fh:
        for pid, oid, cents in csv.reader(fh):
            if pid == "payment_id":
                continue
            cents = int(cents)
            if oid in orders:
                by_order[oid].append((pid, cents))
            else:
                orphans.append((pid, oid, cents))

    rows = []
    counts = defaultdict(int)
    matched_clean = 0
    split_reconciled = 0

    for oid in sorted(orders):
        amt = orders[oid]
        pays = sorted(by_order.get(oid, []))
        if not pays:
            rows.append((oid, "MISSING_PAYMENT", amt, 0))
        elif len(pays) == 1:
            if pays[0][1] == amt:
                matched_clean += 1
            else:
                rows.append((oid, "AMOUNT_MISMATCH", amt, pays[0][1]))
        else:
            total = sum(c for _, c in pays)
            if total == amt:
                split_reconciled += 1  # RECONCILED_SPLIT: clean, no report row
            else:
                rows.append((oid, "DUPLICATE_OVERPAY", amt, total))

    for pid, oid, cents in orphans:
        rows.append((pid, "UNKNOWN_ORDER", "", cents))

    for r in rows:
        counts[r[1]] += 1

    out_path = os.path.join(DATA_DIR, "discrepancies.csv")
    with open(out_path, "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(["order_or_payment_id", "category", "order_amount", "paid_amount"])
        w.writerows(rows)

    print(f"report written to {out_path}")
    print(f"matched_clean={matched_clean}")
    print(f"reconciled_split={split_reconciled}")
    for cat in ("MISSING_PAYMENT", "UNKNOWN_ORDER", "AMOUNT_MISMATCH", "DUPLICATE_OVERPAY"):
        print(f"{cat}={counts[cat]}")


if __name__ == "__main__":
    main()

"""Tests for the order-to-payment reconciliation.

The fixture runs gen_data.py and reconcile.py exactly once. Every assertion is
computed independently from the raw sources (orders.db / payments.csv) or from
fixed planted parameters -- never from reconcile.py's internal logic.
"""
import csv
import os
import sqlite3
import subprocess
import sys

import pytest

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DATA = os.path.join(ROOT, "data")

# Planted parameters (mirrored from gen_data.py, kept explicit here).
NO_PAYMENT_IDS = [f"ORD-{i:04d}" for i in range(140, 148)]          # 8
SPLIT_PAID_IDS = ["ORD-0130", "ORD-0131"]                           # RECONCILED_SPLIT
OVERPAID_IDS = ["ORD-0132", "ORD-0133"]                             # DUPLICATE_OVERPAY
MISMATCH_IDS = [f"ORD-{i:04d}" for i in range(124, 130)]            # 6
UNKNOWN_ORDER_REFS = [f"ORD-950{k}" for k in range(1, 6)]           # 5 orphan payments


def _run(script):
    subprocess.run([sys.executable, os.path.join(ROOT, script)], cwd=ROOT, check=True)


@pytest.fixture(scope="module", autouse=True)
def pipeline():
    _run("gen_data.py")
    _run("reconcile.py")


def load_orders():
    conn = sqlite3.connect(os.path.join(DATA, "orders.db"))
    try:
        return {oid: amt for oid, amt in conn.execute(
            "SELECT order_id, amount_cents FROM orders")}
    finally:
        conn.close()


def load_payments():
    with open(os.path.join(DATA, "payments.csv"), newline="") as fh:
        return [
            (pid, oid, int(cents))
            for pid, oid, cents in csv.reader(fh)
            if pid != "payment_id"
        ]


def load_report():
    with open(os.path.join(DATA, "discrepancies.csv"), newline="") as fh:
        reader = csv.DictReader(fh)
        assert reader.fieldnames == [
            "order_or_payment_id", "category", "order_amount", "paid_amount"]
        return list(reader)


def test_sources_shape():
    orders = load_orders()
    payments = load_payments()
    assert len(orders) == 150
    # 132 clean + 6 mismatch + 4 double (2 split -> 2 extra) + 5 unknown
    assert len(payments) == 132 + 6 + 4 + 2 + 5


def test_category_counts_exact():
    report = load_report()
    by_cat = {}
    for row in report:
        by_cat.setdefault(row["category"], []).append(row["order_or_payment_id"])
    assert len(by_cat.get("MISSING_PAYMENT", [])) == 8
    assert len(by_cat.get("UNKNOWN_ORDER", [])) == 5
    assert len(by_cat.get("AMOUNT_MISMATCH", [])) == 6
    assert len(by_cat.get("DUPLICATE_OVERPAY", [])) == 2
    # no other categories in the report
    assert set(by_cat) == {
        "MISSING_PAYMENT", "UNKNOWN_ORDER", "AMOUNT_MISMATCH", "DUPLICATE_OVERPAY"}


def test_planted_ids_landed_in_right_categories():
    report = load_report()
    ids_by_cat = {}
    for row in report:
        ids_by_cat.setdefault(row["category"], set()).add(row["order_or_payment_id"])
    assert ids_by_cat["MISSING_PAYMENT"] == set(NO_PAYMENT_IDS)
    assert set(UNKNOWN_ORDER_REFS).issubset(ids_by_cat["UNKNOWN_ORDER"])
    assert ids_by_cat["AMOUNT_MISMATCH"] == set(MISMATCH_IDS)
    assert ids_by_cat["DUPLICATE_OVERPAY"] == set(OVERPAID_IDS)
    # the two split-paid orders must be absent from the report entirely
    reported_ids = {row["order_or_payment_id"] for row in report}
    for oid in SPLIT_PAID_IDS:
        assert oid not in reported_ids


def test_split_paid_sums_exactly():
    """Independent check that the 2 split-paid orders really sum to their amount."""
    orders = load_orders()
    sums = {}
    for _, oid, cents in load_payments():
        if oid in SPLIT_PAID_IDS:
            sums[oid] = sums.get(oid, 0) + cents
    assert len(sums) == 2
    for oid in SPLIT_PAID_IDS:
        assert sums[oid] == orders[oid]


def test_overpaid_sums_exceed():
    orders = load_orders()
    sums = {}
    for _, oid, cents in load_payments():
        if oid in OVERPAID_IDS:
            sums[oid] = sums.get(oid, 0) + cents
    assert len(sums) == 2
    for oid in OVERPAID_IDS:
        assert sums[oid] > orders[oid]


def test_matched_clean_count():
    """Orders paid by exactly one payment of exactly the right amount: 150 - 8 - 6 - 4."""
    orders = load_orders()
    per_order = {}
    for _, oid, cents in load_payments():
        if oid in orders:  # ignore orphan payments
            per_order.setdefault(oid, []).append(cents)
    clean = sum(
        1 for oid, cents_list in per_order.items()
        if len(cents_list) == 1 and cents_list[0] == orders[oid]
    )
    assert clean == 150 - 8 - 6 - 4 == 132


def test_net_identity_computed_independently():
    """sum(order amounts) - sum(matched payment amounts)
       == net of the discrepancies as listed in the report."""
    orders = load_orders()

    known_ids = set(orders)
    paid_known = sum(
        cents for _, oid, cents in load_payments() if oid in known_ids)

    side_a = sum(orders.values()) - paid_known

    side_b = 0
    for row in load_report():
        cat = row["category"]
        if cat == "MISSING_PAYMENT":
            side_b += int(row["order_amount"])          # unpaid in full
        elif cat == "AMOUNT_MISMATCH":
            side_b += int(row["order_amount"]) - int(row["paid_amount"])
        elif cat == "DUPLICATE_OVERPAY":
            side_b += int(row["order_amount"]) - int(row["paid_amount"])
        elif cat == "UNKNOWN_ORDER":
            pass                                        # never matched an order
        else:
            raise AssertionError(f"unexpected category {cat}")

    assert side_a == side_b

